ALTER POLICY "Users can read recordings for assigned leads or admin/team_lead" ON public.call_recordings USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'team_leader') OR EXISTS(SELECT 1 FROM public.leads l JOIN public.profiles p ON p.id=coalesce(l.assigned_to,l.assigned_agent_id) WHERE l.id=call_recordings.lead_id AND p.user_id=auth.uid()));
ALTER POLICY "Users can read messages for assigned leads or admin/team_leader" ON public.whatsapp_interactions USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'team_leader') OR EXISTS(SELECT 1 FROM public.leads l JOIN public.profiles p ON p.id=coalesce(l.assigned_to,l.assigned_agent_id) WHERE l.id=whatsapp_interactions.lead_id AND p.user_id=auth.uid()));
ALTER POLICY "Read own reports or supervisors read all" ON public.call_reports USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'team_leader') OR EXISTS(SELECT 1 FROM public.profiles p JOIN public.leads l ON l.id=call_reports.lead_id WHERE p.user_id=auth.uid() AND p.id=call_reports.agent_id AND p.id=coalesce(l.assigned_to,l.assigned_agent_id)));
ALTER POLICY "Agents update own reports" ON public.call_reports USING (EXISTS(SELECT 1 FROM public.profiles p JOIN public.leads l ON l.id=call_reports.lead_id WHERE p.user_id=auth.uid() AND p.id=call_reports.agent_id AND p.id=coalesce(l.assigned_to,l.assigned_agent_id))) WITH CHECK (EXISTS(SELECT 1 FROM public.profiles p JOIN public.leads l ON l.id=call_reports.lead_id WHERE p.user_id=auth.uid() AND p.id=call_reports.agent_id AND p.id=coalesce(l.assigned_to,l.assigned_agent_id)));
ALTER POLICY "Agents read own or assigned-lead activity" ON public.crm_activities USING (EXISTS(SELECT 1 FROM public.profiles p JOIN public.leads l ON l.id=crm_activities.lead_id WHERE p.user_id=auth.uid() AND p.id=coalesce(l.assigned_to,l.assigned_agent_id)));
ALTER POLICY "Users log activity as themselves" ON public.crm_activities WITH CHECK (actor_user_id=auth.uid() AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'team_leader') OR EXISTS(SELECT 1 FROM public.profiles p JOIN public.leads l ON l.id=crm_activities.lead_id WHERE p.user_id=auth.uid() AND p.id=coalesce(l.assigned_to,l.assigned_agent_id))));
ALTER POLICY "Users read events for assigned leads or admin/team_lead" ON public.lead_events USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'team_leader') OR EXISTS(SELECT 1 FROM public.profiles p JOIN public.leads l ON l.id=lead_events.lead_id WHERE p.user_id=auth.uid() AND p.id=coalesce(l.assigned_to,l.assigned_agent_id)));
ALTER POLICY "Agents create own follow-ups" ON public.follow_up_events WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'team_leader') OR EXISTS(SELECT 1 FROM public.profiles p JOIN public.leads l ON l.id=follow_up_events.lead_id WHERE p.user_id=auth.uid() AND p.id=follow_up_events.agent_id AND p.id=coalesce(l.assigned_to,l.assigned_agent_id)));
ALTER POLICY "Read own leads or supervisors read all" ON public.leads USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'team_leader') OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=auth.uid() AND p.id=coalesce(leads.assigned_to,leads.assigned_agent_id)));
ALTER POLICY "Update own leads or supervisors update all" ON public.leads USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'team_leader') OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=auth.uid() AND p.id=coalesce(leads.assigned_to,leads.assigned_agent_id))) WITH CHECK (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'team_leader') OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=auth.uid() AND p.id=coalesce(leads.assigned_to,leads.assigned_agent_id)));